	pub fn new(nodes: &[usize]) -> Self {
		assert_eq!(nodes.len(), Self::NODE_COUNT, "generated Verilog-A node count mismatch");
		let mut mapped = [0usize; Self::NODE_COUNT];
		mapped.copy_from_slice(nodes);
		let params = Parameters::new_box();
		let model_params = params.clone();
		Self {
			nodes: mapped,
			branches: [0usize; Self::BRANCH_COUNT],
			params,
			model_params,
			param_given: boxed_zero_bool_array::<{ Self::PARAMETER_COUNT }>(),
			model_param_given: boxed_zero_bool_array::<{ Self::PARAMETER_COUNT }>(),
			multiplicity: 1.0,
			stamp_state: StampState::new_box(),
			time: 0.0,
			timestep: 0.0,
			ddt_coefficients: GeneratedDdtCoefficients::inactive(),
			canonical_reactive: boxed_zero_f64_array(),
		}
	}

	#[doc(hidden)]
	pub fn capture_rollback_state(&self) -> GeneratedVerilogARollbackState {
		let mut values = Vec::with_capacity(110);
		values.extend_from_slice(&self.stamp_state.ddt_current);
		values.extend_from_slice(&self.stamp_state.ddt_previous);
		values.extend_from_slice(&self.stamp_state.ddt_older);
		values.extend_from_slice(&self.stamp_state.ddt_derivative_current);
		values.extend_from_slice(&self.stamp_state.ddt_derivative_previous);
		values.extend_from_slice(&self.stamp_state.idt_current);
		values.extend_from_slice(&self.stamp_state.idt_candidate_previous);
		values.extend_from_slice(&self.stamp_state.idt_input_current);
		values.extend_from_slice(&self.stamp_state.idt_previous);
		values.extend_from_slice(&self.stamp_state.idt_older);
		values.extend_from_slice(&self.stamp_state.idt_input_previous);
		let mut flags = Vec::with_capacity(44);
		flags.extend_from_slice(&self.stamp_state.ddt_initialized);
		flags.extend_from_slice(&self.stamp_state.idt_initialized);
		flags.extend_from_slice(&self.stamp_state.ddt_candidate_valid);
		flags.extend_from_slice(&self.stamp_state.idt_candidate_valid);
		GeneratedVerilogARollbackState { values, flags }
	}

	#[doc(hidden)]
	pub fn restore_rollback_state(&mut self, state: &GeneratedVerilogARollbackState) {
		debug_assert_eq!(state.values.len(), 110);
		debug_assert_eq!(state.flags.len(), 44);
		let mut rollback_values = state.values.as_slice();
		let (field, remaining) = rollback_values.split_at(Self::DDT_STATE_COUNT);
		self.stamp_state.ddt_current.copy_from_slice(field);
		rollback_values = remaining;
		let (field, remaining) = rollback_values.split_at(Self::DDT_STATE_COUNT);
		self.stamp_state.ddt_previous.copy_from_slice(field);
		rollback_values = remaining;
		let (field, remaining) = rollback_values.split_at(Self::DDT_STATE_COUNT);
		self.stamp_state.ddt_older.copy_from_slice(field);
		rollback_values = remaining;
		let (field, remaining) = rollback_values.split_at(Self::DDT_STATE_COUNT);
		self.stamp_state.ddt_derivative_current.copy_from_slice(field);
		rollback_values = remaining;
		let (field, remaining) = rollback_values.split_at(Self::DDT_STATE_COUNT);
		self.stamp_state.ddt_derivative_previous.copy_from_slice(field);
		rollback_values = remaining;
		let (field, remaining) = rollback_values.split_at(Self::IDT_STATE_COUNT);
		self.stamp_state.idt_current.copy_from_slice(field);
		rollback_values = remaining;
		let (field, remaining) = rollback_values.split_at(Self::IDT_STATE_COUNT);
		self.stamp_state.idt_candidate_previous.copy_from_slice(field);
		rollback_values = remaining;
		let (field, remaining) = rollback_values.split_at(Self::IDT_STATE_COUNT);
		self.stamp_state.idt_input_current.copy_from_slice(field);
		rollback_values = remaining;
		let (field, remaining) = rollback_values.split_at(Self::IDT_STATE_COUNT);
		self.stamp_state.idt_previous.copy_from_slice(field);
		rollback_values = remaining;
		let (field, remaining) = rollback_values.split_at(Self::IDT_STATE_COUNT);
		self.stamp_state.idt_older.copy_from_slice(field);
		rollback_values = remaining;
		let (field, remaining) = rollback_values.split_at(Self::IDT_STATE_COUNT);
		self.stamp_state.idt_input_previous.copy_from_slice(field);
		rollback_values = remaining;
		let mut rollback_flags = state.flags.as_slice();
		let (field, remaining) = rollback_flags.split_at(Self::DDT_STATE_COUNT);
		self.stamp_state.ddt_initialized.copy_from_slice(field);
		rollback_flags = remaining;
		let (field, remaining) = rollback_flags.split_at(Self::IDT_STATE_COUNT);
		self.stamp_state.idt_initialized.copy_from_slice(field);
		rollback_flags = remaining;
		let (field, remaining) = rollback_flags.split_at(Self::DDT_STATE_COUNT);
		self.stamp_state.ddt_candidate_valid.copy_from_slice(field);
		rollback_flags = remaining;
		let (field, remaining) = rollback_flags.split_at(Self::IDT_STATE_COUNT);
		self.stamp_state.idt_candidate_valid.copy_from_slice(field);
		rollback_flags = remaining;
		debug_assert!(rollback_values.is_empty());
		debug_assert!(rollback_flags.is_empty());
	}

	#[doc(hidden)]
	pub fn capture_persistent_state(&self) -> GeneratedVerilogAPersistentState {
		let event_variables = Vec::new();
		GeneratedVerilogAPersistentState {
			ddt_previous: self.stamp_state.ddt_previous.to_vec(),
			ddt_older: self.stamp_state.ddt_older.to_vec(),
			ddt_derivative_previous: self.stamp_state.ddt_derivative_previous.to_vec(),
			ddt_initialized: self.stamp_state.ddt_initialized.to_vec(),
			idt_previous: self.stamp_state.idt_previous.to_vec(),
			idt_older: self.stamp_state.idt_older.to_vec(),
			idt_input_previous: self.stamp_state.idt_input_previous.to_vec(),
			idt_initialized: self.stamp_state.idt_initialized.to_vec(),
			event_variables,
			limiter_anchor: Vec::new(),
			limiter_initialized: Vec::new(),
		}
	}

	#[doc(hidden)]
	pub fn validate_persistent_state_shape(&self, state: &GeneratedVerilogAPersistentState) -> Result<(), String> {
		if state.ddt_previous.len() != Self::DDT_STATE_COUNT || state.ddt_older.len() != Self::DDT_STATE_COUNT || state.ddt_derivative_previous.len() != Self::DDT_STATE_COUNT || state.ddt_initialized.len() != Self::DDT_STATE_COUNT {
			return Err(format!("generated ddt checkpoint shape mismatch: expected {}, found {} / {} / {} / {}", Self::DDT_STATE_COUNT, state.ddt_previous.len(), state.ddt_older.len(), state.ddt_derivative_previous.len(), state.ddt_initialized.len()));
		}
		if state.idt_previous.len() != Self::IDT_STATE_COUNT || state.idt_older.len() != Self::IDT_STATE_COUNT || state.idt_input_previous.len() != Self::IDT_STATE_COUNT || state.idt_initialized.len() != Self::IDT_STATE_COUNT {
			return Err(format!("generated idt checkpoint shape mismatch: expected {}, found {} / {} / {} / {}", Self::IDT_STATE_COUNT, state.idt_previous.len(), state.idt_older.len(), state.idt_input_previous.len(), state.idt_initialized.len()));
		}
		if state.event_variables.len() != 0 {
			return Err(format!("generated event-state checkpoint shape mismatch: expected 0, found {}", state.event_variables.len()));
		}
		if state.ddt_previous.iter().chain(&state.ddt_older).chain(&state.ddt_derivative_previous).chain(&state.idt_previous).chain(&state.idt_older).chain(&state.idt_input_previous).chain(&state.limiter_anchor).any(|value| !value.is_finite()) {
			return Err("generated Verilog-A checkpoint contains non-finite persistent state".to_string());
		}
		if state.event_variables.iter().any(|value| value.is_nan()) {
			return Err("generated Verilog-A checkpoint event state contains NaN".to_string());
		}
		Ok(())
	}

	#[doc(hidden)]
	pub fn restore_persistent_state(&mut self, state: &GeneratedVerilogAPersistentState) -> Result<(), String> {
		self.validate_persistent_state_shape(state)?;
		self.stamp_state.ddt_previous.copy_from_slice(&state.ddt_previous);
		self.stamp_state.ddt_current.copy_from_slice(&state.ddt_previous);
		self.stamp_state.ddt_older.copy_from_slice(&state.ddt_older);
		self.stamp_state.ddt_derivative_previous.copy_from_slice(&state.ddt_derivative_previous);
		self.stamp_state.ddt_derivative_current.copy_from_slice(&state.ddt_derivative_previous);
		self.stamp_state.ddt_initialized.copy_from_slice(&state.ddt_initialized);
		self.stamp_state.idt_previous.copy_from_slice(&state.idt_previous);
		self.stamp_state.idt_current.copy_from_slice(&state.idt_previous);
		self.stamp_state.idt_candidate_previous.copy_from_slice(&state.idt_previous);
		self.stamp_state.idt_older.copy_from_slice(&state.idt_older);
		self.stamp_state.idt_input_previous.copy_from_slice(&state.idt_input_previous);
		self.stamp_state.idt_input_current.copy_from_slice(&state.idt_input_previous);
		self.stamp_state.idt_initialized.copy_from_slice(&state.idt_initialized);
		self.stamp_state.ddt_candidate_valid.fill(false);
		self.stamp_state.idt_candidate_valid.fill(false);
		Ok(())
	}

	#[inline]
	pub fn set_branch_indices(&mut self, branches: &[usize]) {
		assert_eq!(branches.len(), Self::BRANCH_COUNT, "generated Verilog-A branch count mismatch");
		self.branches.copy_from_slice(branches);
	}

	pub fn set_parameter(&mut self, name: &str, value: f64) -> Result<(), String> {
		self.apply_parameters(&[GeneratedParameterAssignment::for_declared_scope(name, value)])
	}

	/// Return whether `name` resolves to a canonical parameter or alias.
	#[inline]
	pub fn has_parameter(name: &str) -> bool {
		let lower = name.to_ascii_lowercase();
		parameter_index_for_name(lower.as_str()).is_some()
	}

	/// Atomically apply model-card and instance parameter assignments.
	///
	/// This is the efficient construction path: dependent defaults and complete
	/// range validation run once after every assignment has been staged.
	pub fn apply_parameters(&mut self, assignments: &[GeneratedParameterAssignment<'_>]) -> Result<(), String> {
		let mut params = self.params.clone();
		let mut model_params = self.model_params.clone();
		let mut param_given = self.param_given.clone();
		let mut model_param_given = self.model_param_given.clone();
		for assignment in assignments {
			let lower = assignment.name.to_ascii_lowercase();
			let Some(index) = parameter_index_for_name(lower.as_str()) else {
				return Err(format!("unknown parameter '{}' for generated Verilog-A model 'bsimsoi'", assignment.name));
			};
			validate_parameter_scalar_metadata(index, assignment.value)?;
			let is_model = PARAMETER_MODEL_FLAGS[index];
			let is_dual_scope = PARAMETER_DUAL_SCOPE_FLAGS[index];
			match assignment.origin {
				GeneratedParameterOrigin::DeclaredScope if is_model => {
					params.values[index] = assignment.value;
					model_params.values[index] = assignment.value;
					param_given[index] = true;
					model_param_given[index] = true;
				}
				GeneratedParameterOrigin::DeclaredScope => {
					params.values[index] = assignment.value;
					param_given[index] = true;
				}
				GeneratedParameterOrigin::ModelCard if is_model => {
					params.values[index] = assignment.value;
					model_params.values[index] = assignment.value;
					param_given[index] = true;
					model_param_given[index] = true;
				}
				GeneratedParameterOrigin::ModelCard if is_dual_scope => {
					model_params.values[index] = assignment.value;
					model_param_given[index] = true;
				}
				GeneratedParameterOrigin::Instance if !is_model => {
					params.values[index] = assignment.value;
					param_given[index] = true;
				}
				GeneratedParameterOrigin::ModelCard | GeneratedParameterOrigin::Instance => {
					let declared = if is_model { "model-card" } else { "instance" };
					let supplied = match assignment.origin {
						GeneratedParameterOrigin::ModelCard => "model-card",
						GeneratedParameterOrigin::Instance => "instance",
						GeneratedParameterOrigin::DeclaredScope => unreachable!(),
					};
					return Err(format!("parameter '{}' is declared for {} assignment and cannot be assigned from {} scope", PARAMETER_DISPLAY_NAMES[index], declared, supplied));
				}
			}
		}
		// Model storage is finalized first, but ranges that reference instance
		// geometry are validated only on the completed effective vector below.
		Self::finalize_parameter_vector(model_params.as_mut(), model_param_given.as_ref(), true)?;
		for index in 0..Self::PARAMETER_COUNT {
			if PARAMETER_MODEL_FLAGS[index] {
				params.values[index] = model_params.values[index];
				param_given[index] = model_param_given[index];
			} else if PARAMETER_DUAL_SCOPE_FLAGS[index] && !param_given[index] {
				params.values[index] = model_params.values[index];
			}
		}
		Self::finalize_parameter_vector(params.as_mut(), param_given.as_ref(), false)?;
		Self::validate_parameter_vector(params.as_ref())?;
		self.commit_parameter_state(params, model_params, param_given, model_param_given);
		Ok(())
	}

	/// Recompute non-given dependent defaults atomically.
	pub fn finalize_parameters(&mut self) -> Result<(), String> {
		let mut params = self.params.clone();
		let mut model_params = self.model_params.clone();
		let param_given = self.param_given.clone();
		let model_param_given = self.model_param_given.clone();
		// Defer cross-scope range validation until model and instance storage are merged.
		Self::finalize_parameter_vector(model_params.as_mut(), model_param_given.as_ref(), true)?;
		for index in 0..Self::PARAMETER_COUNT {
			if PARAMETER_MODEL_FLAGS[index] {
				params.values[index] = model_params.values[index];
			} else if PARAMETER_DUAL_SCOPE_FLAGS[index] && !param_given[index] {
				params.values[index] = model_params.values[index];
			}
		}
		Self::finalize_parameter_vector(params.as_mut(), param_given.as_ref(), false)?;
		Self::validate_parameter_vector(params.as_ref())?;
		self.commit_parameter_state(params, model_params, param_given, model_param_given);
		Ok(())
	}

	/// Validate the complete parameter vector after finalizing dependent defaults.
	pub fn validate_parameters(&self) -> Result<(), String> {
		Self::validate_parameter_vector(self.params.as_ref())
	}

	fn validate_parameter_vector(params: &Parameters) -> Result<(), String> {
		for index in 0..Self::PARAMETER_COUNT {
			let value = read_parameter_slot(params, index);
			validate_parameter_metadata(params, index, value)?;
		}
		Ok(())
	}

